#!/bin/sh
# Builds ~/.config/starship.toml = prompt structure + palette.
# Starship reads a single file, so the palette cannot live in an include.
#  - structure: dotfiles, starship/.config/starship/structure.toml
#  - palette: generated by noctalia (cache/noctalia/starship-palette.toml),
#    otherwise the
#    default one shipped in the dotfiles.
# Called by the noctalia template (post_hook) and by setup-machine.sh.
cfg="${XDG_CONFIG_HOME:-$HOME/.config}"
dir="$cfg/starship"
structure="$dir/structure.toml"
palette="${XDG_CACHE_HOME:-$HOME/.cache}/noctalia/starship-palette.toml"
[ -f "$palette" ] || palette="$dir/palette-default.toml"
[ -f "$structure" ] || { echo "starship-build: $structure missing" >&2; exit 1; }
tmp=$(mktemp "$cfg/.starship.toml.XXXXXX") || exit 1
{ cat "$structure"; echo; cat "$palette"; } > "$tmp" && mv "$tmp" "$cfg/starship.toml"
